import {freeHomeAssets} from './assets/home/free-assets.js';
import {setupPwa} from './install.js';
import {applyTheme,themeOptions} from './theme.js';
import {nextOccurrence} from './dates.js';
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7v10H3Z M9 20v-7h6v7',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',photo:'M3 3h18v18H3Z M3 16l5-5 4 4 3-3 6 6 M16 7h.01',music:'M9 18V5l12-2v13 M9 5l12-2 M9 18a3 3 0 1 1-3-3h3 M21 16a3 3 0 1 1-3-3h3',calendar:'M4 5h16v16H4Z M16 3v4 M8 3v4 M4 10h16 M8 14h2 M14 14h2',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z',plan:'M9 4h11v17H4V4h5 M9 3h6v4H9Z M8 12l2 2 5-5 M8 18h8',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',arrow:'M5 12h14 M14 7l5 5-5 5',plus:'M12 5v14 M5 12h14',lock:'M6 10h12v11H6Z M8 10V6a4 4 0 0 1 8 0v4',close:'m6 6 12 12 M18 6 6 18',check:'m4 12 5 5L20 6',edit:'m4 16 12-12 4 4L8 20H4Z',trash:'M3 6h18 M9 6V3h6v3 M6 6l1 15h10l1-15',back:'m14 5-7 7 7 7',play:'m8 4 12 8-12 8Z',cloud:'M7 18H6a5 5 0 1 1 1-10 6 6 0 0 1 11 0 5 5 0 0 1 0 10h-1 M12 12v9 m-3-6 3-3 3 3',note:'M4 3h16v18H4Z M8 8h8 M8 12h8 M8 16h5',sun:'M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10 M12 1v3 M12 20v3 M1 12h3 M20 12h3 M4 4l2 2 M18 18l2 2 M4 20l2-2 M18 6l2-2'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round"><path d="${paths[name]||paths.spark}"/></svg>`;
const nav=[['inicio','home','Nuestro espacio'],['album','photo','Nuestro álbum'],['recuerdos','heart','La historia'],['musica','music','Nuestra música'],['calendario','calendar','Días especiales'],['planes','plan','Planes juntos'],['conectar','spark','Conectar'],['hogar','home','Nuestro hogar']];
const bgAudio=new Audio('./regalo/musica.mp3');bgAudio.preload='auto';bgAudio.loop=true;
let musicUnlocked=false,currentTrack={id:'original',title:'Nuestra canción',src:'./regalo/musica.mp3'};
async function tryMusic(){if(!bgAudio.paused)return true;try{await bgAudio.play();musicUnlocked=true;return true;}catch{return false;}}
function unlockMusic(){if(musicUnlocked)return;tryMusic();}
function setTrack(src,title,id){if(!src)return;if(bgAudio.src!==new URL(src,location.href).href){bgAudio.src=src;bgAudio.load();}currentTrack={src,title,id};tryMusic();updateMiniPlayer();}
function updateMiniPlayer(){const el=document.querySelector('#global-player');if(!el)return;el.innerHTML=`<button class="icon-button" data-action="music-toggle" aria-label="${bgAudio.paused?'Reproducir':'Pausar'}">${icon(bgAudio.paused?'play':'close')}</button><div><small>SONANDO AHORA</small><b>${esc(currentTrack.title)}</b></div><a href="#musica" class="text-link">Música</a>`;}
let state,view=location.hash.slice(1)||'inicio',filter='Todos',month=new Date().getMonth(),year=new Date().getFullYear(),photos=[],drivePhotos=[],drivePage='',photoSource='local',ideaIndex=0,pickerId=sessionStorage.getItem('pickerId')||'',search='',toastTimer;
const moods={feliz:['☀','Feliz'],tranquilo:['≈','En calma'],cansado:['☾','Sin energía'],sensible:['♡','Sensible'],abrazo:['∞','Necesito un abrazo']};
const items=kind=>state.items.filter(i=>i.kind===kind);
function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),5000);}
async function api(url,options={}){
 const r=await fetch(url,{...options,headers:{...(options.body && !(options.body instanceof Blob)?{'Content-Type':'application/json'}:{}),...(state?.csrf?{'X-CSRF-Token':state.csrf}:{}),...options.headers}});
 const data=await r.json();if(!r.ok)throw Error(data.error||'No pudimos completar la acción.');return data;
}
async function refresh(render=true){state=await api('/api/state');if(render)draw();}
function dateLabel(date,options={}){if(!date)return'Sin fecha · un recuerdo para siempre';return new Intl.DateTimeFormat('es-CO',{day:'numeric',month:'long',...options}).format(new Date(date+'T12:00:00'));}
function nextDate(d){return nextOccurrence(d.date,d.annual,state.today);}
function upcoming(){return items('event').map(e=>({...e,next:nextDate(e.data)})).filter(e=>e.next>=state.today).sort((a,b)=>a.next.localeCompare(b.next));}
function days(date){return Math.round((Date.parse(date+'T12:00:00Z')-Date.parse(state.today+'T12:00:00Z'))/86400000);}
function heading(kicker,title,sub,action=''){return `<div class="page-heading"><div><p class="eyebrow">${kicker}</p><h1>${title}</h1><p class="muted">${sub}</p></div>${action}</div>`;}
function btn(label,action,kind='primary',extra=''){return `<button class="btn ${kind}" data-action="${action}" ${extra}>${label}</button>`;}
function empty(symbol,title,copy,action=''){return `<div class="empty"><span class="empty-icon">${icon(symbol)}</span><h3>${title}</h3><p>${copy}</p>${action}</div>`;}
function formError(message){const el=modal.querySelector('.form-error');if(el){el.textContent=message;el.focus();}else toast(message);}
function show(content,wide=false){modal.className=wide?'wide':'';modal.innerHTML=`<button class="close icon-button" data-action="close" aria-label="Cerrar">${icon('close')}</button>${content}`;modal.showModal();}
function close(){modal.querySelectorAll('iframe').forEach(f=>f.remove());modal.close();}
function draw(){
 document.documentElement.classList.toggle('home-fullscreen',view==='hogar');
 const names=state.settings.data.names;
 app.innerHTML=`<aside class="sidebar"><a class="brand" href="#inicio"><img src="/icon.svg" alt="" width="39" height="39"><span>Nuestra<br><strong>galaxia</strong></span></a><div class="couple-card"><div class="avatars"><span>${esc(names[0][0])}</span><span>${esc(names[1][0])}</span></div><b>${esc(names.join(' & '))}</b><small>Un pequeño universo, solo nuestro</small></div><p class="nav-label">LO QUE SOMOS</p><nav aria-label="Navegación principal">${nav.map(([id,i,label])=>`<a href="#${id}" ${view===id?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${view===id?'<i></i>':''}</a>`).join('')}</nav><a class="gift-link" href="/regalo/">${icon('sun')}<span>Donde todo floreció<small>Volver a tu regalo original</small></span>${icon('arrow')}</a><div class="sidebar-bottom"><a href="#ajustes" ${view==='ajustes'?'aria-current="page"':''}>${icon('settings')} Nuestro espacio</a><span>${icon('lock')} Privado, como lo nuestro</span></div></aside>
 <div class="workspace"><div id="global-player" class="global-player"></div><header class="topbar"><div class="breadcrumb">Nuestro universo <span>/</span> ${esc(nav.find(n=>n[0]===view)?.[2]||'Ajustes')}</div><div class="topbar-right">${state.demo?`<label class="demo-person">Vista local <select id="demo-person" aria-label="Probar como">${names.map((n,i)=>`<option value="${i}" ${String(i)===state.person?'selected':''}>${esc(n)}</option>`).join('')}</select></label>`:`<span class="session-name">Hola, ${esc(names[Number(state.person)])}</span>`}<button class="avatar-button" data-action="settings" aria-label="Abrir ajustes">${esc(names[Number(state.person)][0])}</button></div></header><main id="main" tabindex="-1">${renderView()}</main><footer class="footer">Hecho para nosotros. Para lo cotidiano y lo extraordinario. ${icon('heart')}</footer></div>`;
 const more=document.createElement('button');more.className='mobile-more';more.dataset.action='more';more.innerHTML=icon('plus')+'<span>Más</span>';document.querySelector('nav').append(more);
 if(view==='album')loadPhotos();updateMiniPlayer();if(view==='hogar'&&homeMode==='room')restoreHomeCamera();
}
function renderView(){switch(view){case'album':return album();case'recuerdos':return memories();case'musica':return music();case'calendario':return calendar();case'planes':return plans();case'conectar':return connect();case'hogar':return hogar();case'ajustes':return settings();default:return dashboard();}}
function dashboard(){const names=state.settings.data.names,start=state.settings.data.startDate,next=upcoming()[0],mine=state.daily.find(d=>d.person===state.person);return `
 ${heading('NUESTRO RINCÓN FAVORITO',`Qué bonito coincidir, ${esc(names[Number(state.person)])}.`,'Un lugar para guardar lo que vivimos y soñar lo que viene.',`<span class="today">${icon('calendar')}${dateLabel(state.today,{weekday:'long'})}</span>`)}
 <section class="hero"><div class="hero-copy"><span class="hero-tag">DOS PERSONAS. UN MISMO UNIVERSO.</span><h2>Lo mejor de la vida<br>es vivirla <em>contigo.</em></h2><p>Los días grandes, las canciones de siempre<br>y esas pequeñas cosas que solo entendemos nosotros.</p><div class="hero-actions"><a class="btn cream" href="#recuerdos">Nuestra historia ${icon('arrow')}</a><a class="hero-secondary" href="#planes">Soñemos el próximo plan</a></div><div class="hero-signature">${esc(names.join(' + '))}<span>siempre hay algo bonito por vivir</span></div></div><div class="hero-art"><img src="/garden.svg" alt="Ilustración de girasoles bajo un sol dorado"><span class="art-note">donde estás tú, florece todo.</span></div></section>
 <div class="stats"><a href="#ajustes" class="stat"><span class="stat-icon">${icon('heart')}</span><div><strong>${start?Math.max(0,-days(start)).toLocaleString('es-CO'):'Nuestra fecha'}</strong><span>${start?'días eligiéndonos':'¿Cuándo comenzó todo?'}</span></div>${icon('arrow')}</a><a href="#recuerdos" class="stat"><span class="stat-icon peach">${icon('photo')}</span><div><strong>${items('memory').length}</strong><span>recuerdos que son hogar</span></div>${icon('arrow')}</a><a href="#planes" class="stat"><span class="stat-icon lilac">${icon('spark')}</span><div><strong>${items('plan').filter(i=>!i.data.done).length}</strong><span>planes por vivir juntos</span></div>${icon('arrow')}</a></div>
 <div class="dashboard-grid"><section class="card daily-card"><div class="section-title"><div><span class="eyebrow">UN MINUTO PARA NOSOTROS</span><h2>¿Cómo está tu corazón hoy?</h2></div>${icon('heart')}</div><p class="muted">A veces, conectar empieza con una pequeña pregunta.</p><div class="moods">${Object.entries(moods).map(([key,[symbol,label]])=>`<button data-action="mood" data-value="${key}" class="mood ${mine?.mood===key?'selected':''}" aria-pressed="${mine?.mood===key}"><span>${symbol}</span>${label}</button>`).join('')}</div><div class="daily-status">${state.daily.length?state.daily.filter(d=>d.mood).map(d=>`<span><b>${esc(names[Number(d.person)])}</b> · ${esc(moods[d.mood]?.[1])}</span>`).join(''):'Este es un espacio para escucharse, sin respuestas correctas.'}</div></section>
 <section class="card upcoming-card"><div class="section-title"><h2>Lo que viene</h2><a href="#calendario" aria-label="Ver calendario">${icon('arrow')}</a></div>${next?`<div class="date-tile"><strong>${Number(next.next.slice(8))}</strong><span>${new Intl.DateTimeFormat('es',{month:'short'}).format(new Date(next.next+'T12:00:00'))}</span></div><h3>${esc(next.data.title)}</h3><p class="muted">${days(next.next)===0?'¡Es hoy!':`Faltan ${days(next.next)} días`} · ${next.data.annual?'Una fecha para celebrar cada año':'Un momento para ustedes'}</p>`:`<div class="upcoming-empty">${icon('calendar')}<p>Los mejores días merecen<br>un lugar especial.</p></div>`}${btn('Guardar una fecha '+icon('plus'),'new-event','secondary')}</section></div>
 <div class="section-title spaced"><div><span class="eyebrow">ASÍ EMPEZÓ NUESTRA GALAXIA</span><h2>Pequeños momentos, grandes recuerdos</h2></div><a class="text-link" href="#recuerdos">Ver la historia ${icon('arrow')}</a></div>
 <div class="memory-grid">${items('memory').slice(-3).map((m,i)=>memoryCard(m,i)).join('')}</div>
 <section class="question-banner"><div class="question-symbol">“</div><div><span class="eyebrow">LA PREGUNTA DE HOY</span><h2>${esc(state.question)}</h2><p>Respondan por separado. Descubran sus respuestas cuando ambos estén listos.</p></div><a class="btn secondary" href="#conectar">Un ratito para dos ${icon('arrow')}</a></section>`;}
function memoryCard(m,i){return `<button class="memory-card" data-action="detail" data-id="${m.id}"><div class="memory-art art-${i%4}"><span class="memory-doodle">${icon(['heart','sun','spark','photo'][i%4])}</span><span class="memory-category">${esc(m.data.category||'Un momento nuestro')}</span></div><div class="memory-copy"><small>${dateLabel(m.data.date)}</small><h3>${esc(m.data.title)}</h3><p>${esc(m.data.body)}</p><span class="text-link">Volver a ese momento ${icon('arrow')}</span></div></button>`;}
function memories(){const all=items('memory').filter(m=>(m.data.title+' '+m.data.body).toLowerCase().includes(search.toLowerCase()));return `${heading('LAS COSAS QUE NOS QUEDAN','Nuestra historia, a nuestra manera.','Un archivo de instantes que siempre vale la pena volver a vivir.',btn(icon('plus')+' Guardar recuerdo','new-memory'))}<div class="toolbar"><label class="search-box">Buscar en nuestra historia<input id="memory-search" value="${esc(search)}" placeholder="Un lugar, una palabra, un momento…"></label><span class="muted">${all.length} recuerdos</span></div><div class="memory-grid">${all.map(memoryCard).join('')}</div>${!all.length?empty('heart','Todavía no hay un recuerdo aquí.','Prueba otra palabra o guarda ese momento que no quieres olvidar.'):''}`;}
function album(){return `${heading('LA VIDA, EN FOTOGRAFÍAS','Nuestro álbum.','Los lugares cambian. Lo bonito es haber estado juntos.',btn(icon('plus')+' Añadir fotos','upload'))}<div class="album-banner"><div class="album-art">${icon('photo')}<span>nosotros,<br><em>una y otra vez.</em></span></div><div><span class="eyebrow">UN ÁLBUM CON MUCHAS HISTORIAS</span><h2>Todos nuestros «¿te acuerdas?»</h2><p class="muted">Trae las fotos que quieran conservar en este espacio. Solo ustedes dos podrán verlas aquí.</p><div class="button-row">${state.settings.data.albumUrl?`<a class="btn secondary" target="_blank" rel="noopener noreferrer" href="${esc(state.settings.data.albumUrl)}">Abrir nuestro Google Fotos ${icon('arrow')}</a>`:btn('Añadir enlace del álbum','settings','secondary')}${btn('Elegir de Google Fotos','picker','text-button')}</div></div></div><div class="toolbar"><div class="tabs" aria-label="Origen de las fotos"><button data-action="photo-source" data-value="local" class="${photoSource==='local'?'active':''}">Nuestro álbum</button><button data-action="photo-source" data-value="drive" class="${photoSource==='drive'?'active':''}">Carpeta de Drive</button></div><span class="muted" id="photo-count"></span></div>${pickerId?`<div class="notice">¿Ya terminaste de elegir en Google Fotos? ${btn('Importar selección','picker-import','secondary')}</div>`:''}<div id="photo-grid" class="photo-grid"><p class="muted">Abriendo el álbum…</p></div><input id="photo-upload" type="file" accept="image/jpeg,image/png,image/webp" multiple hidden>`;}
async function loadPhotos(){try{if(photoSource==='drive'){if(!state.connections.drive){document.querySelector('#photo-grid').innerHTML=empty('cloud','Su carpeta, en un solo lugar.','Conecta Google Drive y elige una carpeta compartida en Ajustes.',btn('Configurar Drive','settings'));return;}const data=await api('/api/drive/photos');drivePhotos=data.files||[];drivePage=data.nextPageToken||'';}else photos=(await api('/api/photos')).photos;if(view!=='album')return;renderPhotos();}catch(e){if(view==='album')document.querySelector('#photo-grid').innerHTML=empty('photo','No pudimos abrir las fotos.',esc(e.message),btn('Volver a intentar','reload-photos','secondary'));}}
function renderPhotos(){const data=photoSource==='drive'?drivePhotos:photos;document.querySelector('#photo-count').textContent=`${data.length} fotos`;document.querySelector('#photo-grid').innerHTML=data.length?data.map(p=>`<button class="photo-tile" data-action="photo" data-id="${esc(p.id)}"><img loading="lazy" src="${photoSource==='drive'?'/api/drive/image/':'/media/'}${encodeURIComponent(p.id)}" alt="${esc(p.name)}"><span>${esc(p.name)}</span></button>`).join('')+(drivePage&&photoSource==='drive'?btn('Ver más fotos','drive-more','secondary'):''):empty('photo','Aquí empieza su álbum.','Sube fotos del celular o elígelas desde Google Fotos. Nada se añade sin que ustedes lo escojan.',btn('Añadir nuestras primeras fotos','upload'));}
function songSource(s){return s.data.audioUrl||'';}
function music(){return `${heading('LA BANDA SONORA DE LO NUESTRO','Hay canciones que suenan a ti.','La música puede acompañarlos por toda la galaxia.',btn(icon('plus')+' Añadir canción','new-song'))}<section class="music-feature"><div class="vinyl"><div>✿</div></div><div><span class="eyebrow">SONANDO EN NUESTRA GALAXIA</span><h2>${esc(currentTrack.title)}</h2><p>La música continúa aunque cambies de sección.</p><div class="button-row">${btn(bgAudio.paused?icon('play')+' Reproducir':'Pausar','music-toggle','secondary')}</div></div><span class="music-feature-note">para escucharnos<br><em>un poquito más.</em></span></section><div class="section-title spaced"><h2>Nuestra selección</h2><span class="muted">MP3 · Spotify · YouTube</span></div><div class="song-grid">${items('song').map(s=>`<article class="card song-card"><div class="song-cover">${icon('music')}</div><span class="eyebrow">${esc(s.data.provider||'Nuestra música')}</span><h3>${esc(s.data.title)}</h3><p>${esc(s.data.body||'Una canción para compartir.')}</p><div class="button-row">${btn(icon('play')+' Reproducir','play-song','secondary',`data-id="${s.id}"`)}${btn(icon('edit'),'edit','icon-button',`data-id="${s.id}" aria-label="Editar canción"`)}</div></article>`).join('')}</div>${!items('song').length?empty('music','¿Cuál será nuestra primera canción?','Puedes pegar un enlace o subir directamente un MP3.',btn('Dedicar una canción','new-song','secondary')):''}<input id="song-upload" type="file" accept="audio/mpeg,.mp3" hidden><p class="fine-print">Spotify y YouTube dependen de las reglas de reproducción de cada servicio. Para reproducción directa y continua, usa un MP3.</p>`;}
function calendar(){const first=new Date(year,month,1),offset=(first.getDay()+6)%7,total=new Date(year,month+1,0).getDate();const events=items('event');const title=new Intl.DateTimeFormat('es',{month:'long',year:'numeric'}).format(first);let cells='';for(let i=0;i<offset;i++)cells+='<div class="calendar-blank"></div>';for(let d=1;d<=total;d++){const date=`${year}-${String(month+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;const on=events.filter(e=>e.data.annual?e.data.date.slice(5)===date.slice(5)&&e.data.date<=date:e.data.date===date);cells+=`<button class="day ${date===state.today?'is-today':''}" data-action="day" data-date="${date}" aria-label="${dateLabel(date,{year:'numeric'})}, ${on.length} eventos"><span>${d}</span>${on.slice(0,2).map(e=>`<small>${esc(e.data.title)}</small>`).join('')}${on.length>2?`<small>+${on.length-2} más</small>`:''}</button>`;}
 return `${heading('UN LUGAR PARA LOS DÍAS QUE IMPORTAN','Que no se nos olvide celebrar.','Cumpleaños, aniversarios, citas y cualquier excusa para estar juntos.',btn(icon('plus')+' Añadir fecha','new-event'))}<div class="calendar-layout"><section class="card calendar-card"><div class="calendar-controls"><h2>${title}</h2><div>${btn(icon('back'),'prev-month','icon-button','aria-label="Mes anterior"')}${btn('Hoy','today','text-button')}${btn(icon('arrow'),'next-month','icon-button','aria-label="Mes siguiente"')}</div></div><div class="calendar-grid">${['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'].map(d=>`<span class="weekday">${d}</span>`).join('')}${cells}</div></section><aside class="card agenda"><span class="eyebrow">PARA IR CONTANDO LOS DÍAS</span><h2>Próximos momentos</h2>${upcoming().slice(0,6).map(e=>`<button class="agenda-item" data-action="detail" data-id="${e.id}"><span>${Number(e.next.slice(8))}<small>${new Intl.DateTimeFormat('es',{month:'short'}).format(new Date(e.next+'T12:00:00'))}</small></span><div><b>${esc(e.data.title)}</b><small>${days(e.next)===0?'Hoy':`En ${days(e.next)} días`}${e.data.annual?' · Cada año':''}</small></div></button>`).join('')||'<p class="muted">Todavía no hay fechas. Empiecen por la que más les haga sonreír.</p>'}<a class="btn secondary" href="/api/calendar.ics">Exportar calendario ${icon('calendar')}</a><p class="fine-print">Importa el archivo en Google Calendar, Apple Calendar u Outlook.</p></aside></div>`;}
function plans(){const list=items('plan').filter(i=>filter==='Todos'||(filter==='Por vivir'?!i.data.done:i.data.done));return `${heading('LO BONITO TAMBIÉN SE PLANTEA','Nos quedan tantos planes.','Una lista compartida para los «algún día» y los «¿y si hoy?».',btn(icon('plus')+' Proponer un plan','new-plan'))}<div class="plan-hero"><div><span class="eyebrow">UNA IDEA PARA SALIR DE LA RUTINA</span><h2>${esc(state.ideas[ideaIndex].title)}</h2><p>${esc(state.ideas[ideaIndex].text)}</p><div class="button-row">${btn('Lo queremos hacer '+icon('plus'),'save-idea','primary')}${btn('Sorpréndenos con otra','shuffle-idea','text-button')}</div></div><div class="plan-illustration" aria-hidden="true">${icon('spark')}<span>¿y si<br><em>nos escapamos?</em></span></div></div><div class="toolbar"><div class="tabs">${['Todos','Por vivir','Vividos'].map(f=>`<button data-action="filter" data-value="${f}" class="${filter===f?'active':''}">${f}</button>`).join('')}</div><span class="muted">${items('plan').filter(i=>i.data.done).length} planes hechos realidad</span></div><div class="plan-grid">${list.map(p=>`<article class="card plan-card ${p.data.done?'done':''}"><div class="section-title"><span class="pill">${esc(p.data.category||'Juntos')}</span>${btn(icon('edit'),'edit','icon-button',`data-id="${p.id}" aria-label="Editar plan"`)}</div><h3>${esc(p.data.title)}</h3><p class="muted">${esc(p.data.body)}</p><small>${p.data.date?dateLabel(p.data.date):'Sin prisa, pero con ganas'}</small><button class="complete-plan" data-action="complete" data-id="${p.id}" aria-pressed="${p.data.done}">${icon(p.data.done?'check':'plus')}${p.data.done?'Un recuerdo más':'Marcar como vivido'}</button></article>`).join('')}</div>${!list.length?empty('plan','Los próximos recuerdos empiezan aquí.','Agreguen una idea, pónganle fecha si quieren y háganla realidad.'):''}`;}
function connect(){const names=state.settings.data.names,mine=state.daily.find(d=>d.person===state.person);return `${heading('CUIDAR LO NUESTRO, UN POQUITO CADA DÍA','Un ratito para dos.','Sin puntuaciones ni rachas que cumplir. Solo una invitación a escucharse.')}<section class="connection-question"><span class="pill">${icon('spark')} La pregunta de hoy</span><h2>${esc(state.question)}</h2><p>Primero respondan a su manera. Las dos respuestas se revelan cuando ambos hayan escrito.</p><form id="answer-form"><label for="answer">Tu respuesta, ${esc(names[Number(state.person)])}</label><textarea id="answer" name="answer" maxlength="3000" required placeholder="Tómate tu tiempo…">${esc(mine?.answer||'')}</textarea><button class="btn primary" type="submit">${mine?.answered?'Actualizar mi respuesta':'Guardar mi respuesta'} ${icon('heart')}</button><p class="inline-error" role="alert"></p></form><div class="answer-grid">${names.map((n,i)=>{const d=state.daily.find(d=>d.person===String(i));return `<article><span class="answer-avatar">${esc(n[0])}</span><b>${esc(n)}</b><p>${d?.answer?esc(d.answer):d?.answered?'Su respuesta está guardada. Se abrirá cuando ambos respondan.':'Todavía está pensando su respuesta.'}</p></article>`;}).join('')}</div></section><div class="section-title spaced"><div><span class="eyebrow">EL AMOR TAMBIÉN ESTÁ EN LOS DETALLES</span><h2>Pequeñas formas de estar cerca</h2></div></div><div class="ritual-grid">${state.ideas.filter(i=>i.category==='Conectar').map((i)=>`<article class="card ritual-card">${icon('heart')}<span class="pill">${i.minutes} min · Para dos</span><h3>${esc(i.title)}</h3><p class="muted">${esc(i.text)}</p>${btn('Guardar como plan','ritual','text-button',`data-index="${state.ideas.indexOf(i)}"`)}</article>`).join('')}</div><div class="section-title spaced"><h2>Te dejo una notita</h2>${btn(icon('plus')+' Escribir algo bonito','new-note','secondary')}</div><div class="note-grid">${items('note').map(n=>`<button class="note-card" data-action="detail" data-id="${n.id}"><span>${icon('note')}</span><h3>${esc(n.data.title)}</h3><p>${esc(n.data.body)}</p><small>De ${esc(names[Number(n.author)]||names[0])}, con cariño</small></button>`).join('')||'<p class="muted">Un «gracias», un «te extraño», un «qué suerte tenerte». Empieza cuando quieras.</p>'}</div>`;}
