const customHomeAssets=new Set(['album','recordplayer','wallcalendar','memorybox','planner','telephone']);
function homeAssetSrc(asset){if(freeHomeAssets[asset])return freeHomeAssets[asset];if(customHomeAssets.has(asset))return `./assets/home/${asset==='wallcalendar'?'calendar':asset}.svg`;return '';}
function homeVisual(id,context='catalog'){const item=homeCatalog[id],src=item&&homeAssetSrc(item.asset);if(!item||!src)return'';const style=context==='scene'?`style="--object-w:${item.w}px;--object-h:${item.h}px"`:'';return `<img class="home-object-art" src="${src}" alt="${esc(item.name)}" ${style}>`;}
function homeCatalogEntries(){return Object.entries(homeCatalog).filter(([,item])=>homeAssetSrc(item.asset));}
let homeRoom='living',homeMode='room',placingItem='',homeAvatarX=48,homeCameraX=.5,homeDrag=null,homeDragSuppressUntil=0;
function restoreHomeCamera(){
 const viewport=document.querySelector('.home-camera');
 if(!viewport)return;
 requestAnimationFrame(()=>{const max=Math.max(0,viewport.scrollWidth-viewport.clientWidth);viewport.scrollLeft=max*homeCameraX;});
}
function rememberHomeCamera(viewport){const max=Math.max(1,viewport.scrollWidth-viewport.clientWidth);homeCameraX=Math.max(0,Math.min(1,viewport.scrollLeft/max));}
function homePlaced(room){return(state.home?.placed||[]).filter(x=>x.room===room);}
function roomScene(h,room){
 const names=state.settings.data.names,person=Number(state.person)||0,placed=homePlaced(homeRoom);
 return `<section class="adventure-room scene-${homeRoom}"><div class="home-camera" aria-label="Habitación panorámica: arrastra para explorar"><div class="home-world" data-action="home-walk">
  <div class="scene-sky"></div><div class="scene-wall">
   <div class="scene-window"><span></span><i></i></div>
   <div class="scene-picture">♡<small>${esc(names.join(' + '))}</small></div>
   ${homeDoors[homeRoom].map(([to,label,arrow],i)=>`<button class="scene-door door-${i}" data-action="home-door" data-room="${to}" aria-label="Ir a ${label}"><span class="door-panel"></span><b>${label}</b><i>${arrow}</i></button>`).join('')}
  </div>
  <div class="scene-floor">
   ${Array.from({length:8},(_,slot)=>{const p=placed.find(x=>Number(x.slot)===slot);return`<button class="scene-slot scene-slot-${slot} ${p?`has-item size-${'real'} place-${homeCatalog[p.item]?.place||'floor'}`:''}" data-action="${p&&homeCatalog[p.item]?.route?'home-tool':'home-slot'}" data-slot="${slot}" ${p&&homeCatalog[p.item]?.route?`data-route="${homeCatalog[p.item].route}"`:''} aria-label="${p?homeCatalog[p.item]?.name:'Espacio para decorar'}">${p?`${homeVisual(p.item,'scene')}<small>${homeCatalog[p.item]?.route?'Abrir '+homeCatalog[p.item]?.name:homeCatalog[p.item]?.name||''}</small>`:(placingItem?'<i>+</i>':'')}</button>`}).join('')}
   <div class="home-avatar person-${person}" style="--walk-x:${homeAvatarX}%"><span class="avatar-head">${esc(names[person][0])}</span><span class="avatar-body"></span><b>${esc(names[person])}</b></div>
  </div>
  <div class="scene-caption"><span>${room[2]}</span><div><b>${room[0]}</b><small>${room[1]}</small></div></div>
 </div></div><div class="camera-hint" aria-hidden="true">↔ Arrastra para explorar</div></section>`;
}
function hogar(){
 const h=state.home||{coins:0,inventory:{},placed:[]},room=homeRooms[homeRoom];
 const hud=`<button class="home-exit" data-action="home-exit" aria-label="Volver al universo">← <span>Universo</span></button><div class="home-game-hud"><div class="home-room-label"><span>${room[2]}</span><div><b>${room[0]}</b><small>Nuestro Hogar</small></div></div><div class="sun-coins"><span>🌻</span><div><b>${h.coins}</b><small>Monedas</small></div></div></div>`;
 if(homeMode==='shop')return `${hud}<div class="home-game-panel"><div class="home-toolbar">${btn('← Volver al cuarto','home-room','secondary')}<h2>Tienda del hogar</h2><div>${btn('Inventario','home-inventory','secondary')}</div></div><div class="shop-grid">${homeCatalogEntries().map(([id,item])=>`<article class="shop-item card"><span class="furniture-preview size-${'catalog'}">${homeVisual(id)}</span><h3>${item.name}</h3><p class="muted">Tienen ${h.inventory?.[id]||0}</p><button class="btn primary" data-action="home-buy" data-item="${id}" data-cost="${item.price}" ${h.coins<item.price?'disabled':''}>🌻 ${item.price}</button></article>`).join('')}</div></div>`;
 if(homeMode==='inventory')return `${hud}<div class="home-game-panel"><div class="home-toolbar">${btn('← Volver','home-room','secondary')}<h2>Inventario</h2><span class="muted">Elige algo para colocarlo.</span></div><div class="inventory-grid">${homeCatalogEntries().filter(([id])=>(h.inventory?.[id]||0)>homePlaced(homeRoom).filter(x=>x.item===id).length).map(([id,item])=>`<button class="inventory-item size-${'catalog'} ${placingItem===id?'selected':''}" data-action="home-select-item" data-item="${id}" data-size="${'catalog'}">${homeVisual(id)}<b>${item.name}</b><small>Disponibles: ${(h.inventory[id]||0)-homePlaced(homeRoom).filter(x=>x.item===id).length}</small></button>`).join('')||'<p class="muted">No hay muebles libres. Visiten la tienda.</p>'}</div></div>`;
 return `<div class="home-game">${hud}${roomScene(h,room)}<div class="game-controls"><button class="game-move" data-action="home-step" data-dir="-1" aria-label="Caminar a la izquierda">←</button><button class="game-bag" data-action="home-inventory">🎒<span>Inventario</span></button><button class="game-shop" data-action="home-shop">🛍️<span>Tienda</span></button><button class="game-map" data-action="home-map">⌂<span>Mapa</span></button><button class="game-move" data-action="home-step" data-dir="1" aria-label="Caminar a la derecha">→</button></div><p class="home-tip">${placingItem?'Toca uno de los + del escenario para colocar '+homeCatalog[placingItem].name+'.':'Toca el suelo para caminar. Toca una puerta para pasar a otra habitación.'}</p></div>`;
}
function settings(){const d=state.settings.data;return `${heading('HECHO A NUESTRA MEDIDA','Nuestro espacio.','Los nombres, las fechas y las conexiones que hacen de este lugar algo suyo.')}<div class="theme-panel card"><div><span class="eyebrow">APARIENCIA</span><h2>¿Cómo se siente nuestra galaxia hoy?</h2><p class="muted">Déjala cambiar con la temporada o elijan un universo cuando quieran.</p></div><div class="theme-choices">${themeOptions().map(([id,label])=>`<button type="button" class="theme-choice ${document.documentElement.dataset.themeChoice===id?'selected':''}" data-action="theme" data-value="${id}"><i class="theme-swatch swatch-${id}"></i><span>${label}</span></button>`).join('')}</div></div><div class="settings-grid"><section class="card"><span class="eyebrow">NOSOTROS DOS</span><h2>Lo que nos hace nosotros</h2><form id="settings-form"><div class="form-row"><label>Tu nombre<input name="name0" required maxlength="40" value="${esc(d.names[0])}"></label><label>Su nombre<input name="name1" required maxlength="40" value="${esc(d.names[1])}"></label></div><label>El día en que empezó nuestra historia<input type="date" name="startDate" max="${state.today}" value="${esc(d.startDate)}"></label><p class="fine-print">Pueden dejarlo vacío y completarlo cuando quieran.</p><label>Enlace de nuestro álbum de Google Fotos<input type="url" name="albumUrl" placeholder="https://photos.app.goo.gl/…" value="${esc(d.albumUrl)}"></label><button class="btn primary">Guardar nuestro espacio</button><p class="inline-error" role="alert"></p></form></section><section class="card"><span class="eyebrow">FOTOS QUE SIGUEN CON NOSOTROS</span><h2>Nuestras conexiones</h2><div class="connection-row"><span class="connection-icon">${icon('photo')}</span><div><b>Google Fotos</b><p>${state.connections.photos?'Cuenta conectada · selecciona qué importar':'Elijan las fotos que quieren traer a la aplicación.'}</p></div></div>${state.connections.photos?btn('Elegir fotos','picker','secondary'):`<a class="btn secondary" ${state.demo?'data-action="google-info" href="#ajustes"':'href="/auth/google?feature=photos"'}>Conectar Google Fotos ${icon('arrow')}</a>`}<p class="fine-print">El enlace compartido abre su álbum en Google Fotos. Para verlo aquí, importen una selección. No se sincroniza automáticamente.</p><hr><div class="connection-row"><span class="connection-icon">${icon('cloud')}</span><div><b>Google Drive</b><p>${state.connections.drive?'Cuenta conectada':'Opcional: ver fotos de una carpeta compartida.'}</p></div></div>${state.connections.drive?`<form id="drive-form"><label>Carpeta compartida<input name="url" required placeholder="https://drive.google.com/drive/folders/…" value="${d.folderId?'https://drive.google.com/drive/folders/'+esc(d.folderId):''}"></label><button class="btn secondary">Conectar carpeta</button><p class="inline-error" role="alert"></p></form>`:`<a class="btn secondary" ${state.demo?'data-action="google-info" href="#ajustes"':'href="/auth/google?feature=drive"'}>Conectar Google Drive ${icon('arrow')}</a>`}<p class="fine-print">Drive solicita permiso de lectura; la aplicación muestra solo la carpeta que elijan. Ambos necesitan acceso a esa carpeta.</p>${!state.demo?btn('Desconectar permisos de Google','disconnect','text-button'):''}</section><section class="card"><span class="eyebrow">SU HISTORIA LES PERTENECE</span><h2>Guardar y salir</h2><p class="muted">Descarga sus recuerdos, planes, canciones, fechas y notas en un archivo. Las fotos se conservan aparte en el servidor.</p><a class="btn secondary" href="/api/export">Descargar nuestros datos ${icon('arrow')}</a>${!state.demo?btn('Cerrar sesión','logout','text-button'):''}<p class="fine-print">${state.demo?'Vista local: los cambios se guardan en este computador. Para compartir entre sus celulares hace falta activar Google y alojar la aplicación.':'Espacio privado: solo las dos cuentas configuradas pueden entrar.'}</p></section><section class="card gift-settings"><img src="/icon.svg" alt="" width="60" height="60"><h2>Siempre habrá girasoles.</h2><p>La carta, las seis flores y el pequeño secreto que dieron comienzo a este universo.</p><a href="/regalo/" class="btn secondary">Abrir el regalo original ${icon('arrow')}</a></section></div>`;}
const kindLabels={memory:['recuerdo','Guardar recuerdo'],song:['canción','Guardar canción'],event:['fecha','Guardar fecha'],plan:['plan','Guardar plan'],note:['nota','Guardar nota']};
function editor(kind,item=null,defaults={}){const d=item?.data||{title:'',body:'',date:'',category:'',url:'',audioUrl:'',audioPath:'',...defaults};const [label,submit]=kindLabels[kind];show(`<span class="eyebrow">UN PEDACITO MÁS DE NOSOTROS</span><h2 id="modal-title">${item?'Editar':'Añadir'} ${label}</h2><form id="item-form" data-kind="${kind}" ${item?`data-id="${item.id}" data-version="${item.version}"`:''}><label>${kind==='song'?'Nombre de la canción':'Título'}<input name="title" required maxlength="120" value="${esc(d.title)}" placeholder="Dale un nombre a este momento"></label>${kind==='song'?`<label>Enlace de Spotify, YouTube o audio directo (opcional)<input name="url" type="url" value="${esc(d.url||'')}" placeholder="https://…"></label><input name="audioUrl" type="hidden" value="${esc(d.audioUrl||'')}"><input name="audioPath" type="hidden" value="${esc(d.audioPath||'')}"><div class="song-upload-box"><p>O súbela directamente en MP3 para reproducirla dentro de la app.</p>${btn(icon('cloud')+' Elegir MP3','choose-song-file','secondary')}<span id="song-file-name" class="muted">${d.audioUrl?'MP3 ya cargado':''}</span></div>`:''}<label>${kind==='song'?'¿Por qué te recuerda a nosotros?':kind==='note'?'Lo que quieres decirle':'Cuéntanos un poquito más'}<textarea name="body" maxlength="5000" rows="4" placeholder="Las pequeñas cosas también merecen guardarse…">${esc(d.body)}</textarea></label>${['event','plan','memory'].includes(kind)?`<div class="form-row"><label>Fecha ${kind==='event'?'':'(opcional)'}<input name="date" type="date" ${kind==='event'?'required':''} value="${esc(d.date)}"></label><label>Categoría<input name="category" maxlength="40" value="${esc(d.category)}"></label></div>`:''}${kind==='event'?`<label class="check-label"><input type="checkbox" name="annual" ${d.annual?'checked':''}> Celebrarlo cada año</label>`:''}<p class="form-error" role="alert" tabindex="-1"></p><div class="form-actions">${item?btn(icon('trash')+' Eliminar','delete','danger',`data-id="${item.id}"`):'<span></span>'}<button class="btn primary" type="submit">${submit} ${icon('check')}</button></div></form>`);}
function detail(id){const i=state.items.find(i=>i.id===id);if(!i)return;show(`<span class="eyebrow">${esc(i.data.category||kindLabels[i.kind][0])}</span><h2 id="modal-title">${esc(i.data.title)}</h2>${i.data.date?`<p class="muted">${dateLabel(i.data.date,{year:'numeric'})}</p>`:''}<p class="detail-body">${esc(i.data.body)}</p><div class="form-actions"><span>De ${esc(state.settings.data.names[Number(i.author)]||'nosotros')}</span>${btn(icon('edit')+' Editar','edit','secondary',`data-id="${id}"`)}</div>`);}
async function mutate(url,method,data,message){await api(url,{method,body:JSON.stringify(data)});close();await refresh();toast(message);}
async function action(el,event=null){const a=el.dataset.action,id=el.dataset.id,item=state?.items.find(i=>i.id===id);if(a?.startsWith('new-')&&kindLabels[a.slice(4)])return editor(a.slice(4));switch(a){
 case'home-exit':location.hash='inicio';return;
 case'home-tool':location.hash=el.dataset.route;return;
 case'home-rooms':homeMode='room';placingItem='';return draw();
 case'home-map':return show(`<span class="eyebrow">NUESTRO HOGAR</span><h2 id="modal-title">¿A dónde vamos?</h2><div class="home-map-grid">${Object.entries(homeRooms).map(([id,r])=>`<button data-action="home-door" data-room="${id}" class="${id===homeRoom?'current':''}"><span>${r[2]}</span><b>${r[0]}</b></button>`).join('')}</div>`);
 case'home-door':if(modal.open)close();homeRoom=el.dataset.room;homeMode='room';homeAvatarX=50;homeCameraX=.5;placingItem='';draw();return;
 case'home-step':homeAvatarX=Math.max(10,Math.min(90,homeAvatarX+Number(el.dataset.dir)*14));return draw();
 case'home-walk':if(event&&Date.now()>homeDragSuppressUntil){const box=el.getBoundingClientRect();homeAvatarX=Math.max(8,Math.min(92,((event.clientX-box.left)/box.width)*100));draw();}return;
 case'home-shop':homeMode='shop';return draw();
 case'home-inventory':homeMode='inventory';return draw();
 case'home-room':homeMode='room';return draw();
 case'home-open':homeRoom=el.dataset.room;homeMode='room';homeCameraX=.5;placingItem='';return draw();
 case'home-select-item':placingItem=el.dataset.item;homeMode='room';draw();return toast('Ahora toca un espacio vacío del cuarto.');
 case'home-buy':await api('/api/home/buy',{method:'POST',body:JSON.stringify({item:el.dataset.item,cost:Number(el.dataset.cost)})});await refresh(false);return draw();
 case'home-slot':if(!placingItem)return toast('Elige primero un mueble del inventario.');await api('/api/home/place',{method:'POST',body:JSON.stringify({item:placingItem,room:homeRoom,slot:Number(el.dataset.slot)})});placingItem='';await refresh(false);return draw();
 case'theme':applyTheme(el.dataset.value);draw();return toast('La galaxia cambió de ambiente.');
 case'more':return show(`<h2 id="modal-title">Todo nuestro universo</h2><div class="more-nav">${nav.map(([id,i,label])=>`<a href="#${id}">${icon(i)}${label}${icon('arrow')}</a>`).join('')}<a href="#ajustes">${icon('settings')}Ajustes${icon('arrow')}</a><a href="/regalo/">${icon('sun')}El regalo original${icon('arrow')}</a></div>`);
 case'close':return close();case'settings':location.hash='ajustes';return;case'detail':return detail(id);case'edit':close();return editor(item.kind,item);
 case'delete':return show(`<h2 id="modal-title">¿Eliminar este ${kindLabels[item.kind][0]}?</h2><p>Se quitará de su espacio compartido. Esta acción no se puede deshacer.</p><div class="button-row">${btn('Conservarlo','close','secondary')}${btn('Sí, eliminar','confirm-delete','danger',`data-id="${id}"`)}</div>`);
 case'confirm-delete':return mutate('/api/items/'+id,'DELETE',{version:item.version},'Contenido eliminado.');
 case'mood':await api('/api/daily',{method:'POST',body:JSON.stringify({field:'mood',value:el.dataset.value})});await refresh();return toast('Gracias por compartir cómo te sientes.');
 case'filter':filter=el.dataset.value;return draw();
 case'shuffle-idea':ideaIndex=(ideaIndex+1+Math.floor(Math.random()*(state.ideas.length-1)))%state.ideas.length;return draw();
 case'save-idea':case'ritual':{const idea=state.ideas[a==='ritual'?Number(el.dataset.index):ideaIndex];return editor('plan',null,{title:idea.title,body:idea.text,category:idea.category});}
 case'complete':await api('/api/items/'+id,{method:'PUT',body:JSON.stringify({...item.data,version:item.version,done:!item.data.done})});await refresh();return toast(item.data.done?'El plan volvió a los pendientes.':'Un plan vivido. Un recuerdo más. ♡');
 case'prev-month':month--;if(month<0){month=11;year--;}return draw();case'next-month':month++;if(month>11){month=0;year++;}return draw();case'today':year=Number(state.today.slice(0,4));month=Number(state.today.slice(5,7))-1;return draw();
 case'day':{const date=el.dataset.date,list=items('event').filter(e=>e.data.annual?e.data.date.slice(5)===date.slice(5)&&e.data.date<=date:e.data.date===date);if(!list.length)return editor('event',null,{date});return show(`<h2 id="modal-title">${dateLabel(date,{year:'numeric'})}</h2>${list.map(e=>`<button class="day-event" data-action="detail" data-id="${e.id}">${esc(e.data.title)} ${icon('arrow')}</button>`).join('')}${btn('Añadir otra fecha','new-on-day','secondary',`data-date="${date}"`)}`);}
 case'new-on-day':close();return editor('event',null,{date:el.dataset.date});
 case'music-toggle':if(bgAudio.paused)await tryMusic();else bgAudio.pause();updateMiniPlayer();if(view==='musica')draw();return;
 case'choose-song-file':document.querySelector('#song-upload-picker')?.remove();{const input=document.createElement('input');input.id='song-upload-picker';input.type='file';input.accept='audio/mpeg,.mp3';input.hidden=true;document.body.append(input);input.click();return;}
 case'play-song':{if(item.data.audioUrl){setTrack(item.data.audioUrl,item.data.title,item.id);return toast('Reproduciendo en Nuestra galaxia.');}return show(`<span class="eyebrow">${esc(item.data.provider)}</span><h2 id="modal-title">${esc(item.data.title)}</h2><p>${esc(item.data.body)}</p><iframe class="player ${item.data.provider==='YouTube'?'video':''}" src="${esc(item.data.embed)}" title="Escuchar ${esc(item.data.title)}" allow="autoplay; clipboard-write; encrypted-media; fullscreen; picture-in-picture" allowfullscreen></iframe><a class="text-link" href="${esc(item.data.url)}" target="_blank" rel="noopener noreferrer">Abrir en ${esc(item.data.provider)} ${icon('arrow')}</a>`,true);}
 case'upload':document.querySelector('#photo-upload').click();return;
 case'photo-source':photoSource=el.dataset.value;return draw();case'reload-photos':return loadPhotos();
 case'drive-more':{const batch=await api('/api/drive/photos?page='+encodeURIComponent(drivePage));drivePhotos.push(...batch.files);drivePage=batch.nextPageToken||'';return renderPhotos();}
 case'photo':{const p=(photoSource==='drive'?drivePhotos:photos).find(p=>p.id===id);return show(`<h2 id="modal-title">${esc(p.name)}</h2><img class="lightbox-photo" src="${photoSource==='drive'?'/api/drive/image/':'/media/'}${encodeURIComponent(id)}" alt="${esc(p.name)}">${photoSource==='local'?btn('Quitar del álbum','delete-photo','text-button',`data-id="${id}"`):''}`,true);}
 case'delete-photo':return show(`<h2 id="modal-title">¿Quitar esta foto?</h2><p>Se elimina la copia de esta aplicación. El original de Google Fotos o del celular no cambia.</p><div class="button-row">${btn('Conservarla','close','secondary')}${btn('Quitar foto','confirm-delete-photo','danger',`data-id="${id}"`)}</div>`);
 case'confirm-delete-photo':return mutate('/api/photos/'+id,'DELETE',{},'Foto eliminada del álbum.');
 case'google-info':return show(`<span class="eyebrow">ESTAMOS EN LA VISTA LOCAL</span><h2 id="modal-title">Conectar su cuenta de Google</h2><p>La aplicación ya incluye la conexión. Para activarla necesita sus credenciales de Google y las dos cuentas autorizadas en el servidor.</p><p>Mientras tanto, pueden subir fotos, añadir canciones y completar su historia. Todo se guarda en este computador.</p>${btn('Entendido','close','primary')}`);
 case'picker':if(!state.connections.photos){if(state.demo)return action({dataset:{action:'google-info'}});location.href='/auth/google?feature=photos';return;}const p=await api('/api/picker',{method:'POST',body:'{}'});pickerId=p.id;sessionStorage.setItem('pickerId',p.id);show(`<h2 id="modal-title">Elijan sus fotos favoritas</h2><p>Se abrirá el selector de Google Fotos. Elijan hasta 30 fotos y regresen para importarlas a su álbum privado.</p><a class="btn primary" href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">Elegir en Google Fotos ${icon('arrow')}</a><p>Cuando terminen:</p>${btn('Importar selección','picker-import','secondary')}`);return;
 case'picker-import':{toast('Importando la selección…');const r=await api('/api/picker/import',{method:'POST',body:JSON.stringify({id:pickerId})});if(r.pending)return toast('Termina de seleccionar las fotos en Google y vuelve a intentar.');pickerId='';sessionStorage.removeItem('pickerId');close();location.hash='album';await refresh();return toast(`${r.imported} fotos importadas.${r.skipped?' Los videos no se importaron.':''}`);}
 case'disconnect':return show(`<h2 id="modal-title">¿Desconectar Google?</h2><p>Se revocarán los permisos de fotos y Drive de tu cuenta. Las fotos que ya importaste seguirán en su álbum; puedes eliminarlas allí.</p>${btn('Desconectar','confirm-disconnect','danger')}`);
 case'confirm-disconnect':await api('/api/google/disconnect',{method:'POST',body:'{}'});close();await refresh();return toast('Google desconectado.');
 case'logout':await api('/api/logout',{method:'POST',body:'{}'});location.reload();return;
 }}
document.addEventListener('pointerdown',event=>{
 const viewport=event.target.closest?.('.home-camera');
 if(!viewport||event.button!==0||event.target.closest('button,a,input,select,textarea'))return;
 homeDrag={viewport,id:event.pointerId,startX:event.clientX,startScroll:viewport.scrollLeft,moved:false};
 viewport.classList.add('is-dragging');viewport.setPointerCapture?.(event.pointerId);
});
document.addEventListener('pointermove',event=>{
 if(!homeDrag||homeDrag.id!==event.pointerId)return;
 const dx=event.clientX-homeDrag.startX;
 if(Math.abs(dx)>5)homeDrag.moved=true;
 homeDrag.viewport.scrollLeft=homeDrag.startScroll-dx;
 rememberHomeCamera(homeDrag.viewport);
});
function endHomeCameraDrag(event){
 if(!homeDrag||homeDrag.id!==event.pointerId)return;
 if(homeDrag.moved){homeDragSuppressUntil=Date.now()+350;rememberHomeCamera(homeDrag.viewport);}
 homeDrag.viewport.classList.remove('is-dragging');homeDrag.viewport.releasePointerCapture?.(event.pointerId);homeDrag=null;
}
document.addEventListener('pointerup',endHomeCameraDrag);document.addEventListener('pointercancel',endHomeCameraDrag);
document.addEventListener('wheel',event=>{const viewport=event.target.closest?.('.home-camera');if(!viewport)return;if(Math.abs(event.deltaY)>Math.abs(event.deltaX)){viewport.scrollLeft+=event.deltaY;rememberHomeCamera(viewport);event.preventDefault();}},{passive:false});
document.addEventListener('pointerdown',unlockMusic,{once:true});
bgAudio.addEventListener('play',updateMiniPlayer);bgAudio.addEventListener('pause',updateMiniPlayer);
document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el)return;event.preventDefault();if(el.disabled)return;el.disabled=true;try{await action(el,event);}catch(e){if(modal.open)formError(e.message);else toast(e.message);}finally{el.disabled=false;}});
document.addEventListener('submit',async event=>{const f=event.target;event.preventDefault();const data=Object.fromEntries(new FormData(f));const submit=f.querySelector('[type="submit"],button:not([type])');if(submit)submit.disabled=true;try{
 if(f.id==='item-form'){const item=state.items.find(i=>i.id===f.dataset.id);const payload={...item?.data,...data,kind:f.dataset.kind,annual:!!data.annual,version:Number(f.dataset.version)};await mutate('/api/items'+(item?'/'+item.id:''),item?'PUT':'POST',payload,'Guardado en su universo. ♡');}
 if(f.id==='settings-form'){await api('/api/settings',{method:'PUT',body:JSON.stringify({names:[data.name0,data.name1],startDate:data.startDate,albumUrl:data.albumUrl,version:state.settings.version})});await refresh();toast('Su espacio, a su manera.');}
 if(f.id==='answer-form'){await api('/api/daily',{method:'POST',body:JSON.stringify({field:'answer',value:data.answer})});await refresh();toast(state.allAnswered?'Sus dos respuestas ya están abiertas. ♡':'Tu respuesta quedó guardada.');}
 if(f.id==='drive-form'){await api('/api/drive/folder',{method:'POST',body:JSON.stringify(data)});await refresh();toast('Carpeta conectada.');}
 }catch(e){const error=f.querySelector('.inline-error,.form-error');if(error)error.textContent=e.message;else toast(e.message);}finally{if(submit)submit.disabled=false;}});
document.addEventListener('change',async event=>{try{
 if(event.target.id==='song-upload-picker'){const file=event.target.files?.[0];if(!file)return;if(file.type!=='audio/mpeg'&&!file.name.toLowerCase().endsWith('.mp3'))throw Error('Selecciona un archivo MP3.');if(file.size>20971520)throw Error('El MP3 puede pesar máximo 20 MB.');toast('Subiendo canción…');const result=await api('/api/music/upload',{method:'POST',body:file,headers:{'Content-Type':'application/octet-stream','X-File-Name':encodeURIComponent(file.name)}});const field=modal.querySelector('input[name="audioUrl"]');if(field)field.value=result.url;const pathField=modal.querySelector('input[name="audioPath"]');if(pathField)pathField.value=result.path;const label=modal.querySelector('#song-file-name');if(label)label.textContent=file.name;event.target.remove();toast('MP3 listo para guardar.');}
if(event.target.id==='demo-person'){await api('/api/demo-person',{method:'POST',body:JSON.stringify({person:event.target.value})});await refresh();}
 if(event.target.id==='photo-upload'){const files=[...event.target.files];if(files.length>30)throw Error('Selecciona hasta 30 fotos por vez.');let count=0;for(const file of files){toast(`Subiendo foto ${count+1} de ${files.length}…`);await api('/api/photos/upload',{method:'POST',body:file,headers:{'Content-Type':'application/octet-stream','X-File-Name':encodeURIComponent(file.name)}});count++;}await refresh();toast(`${count} fotos guardadas en su álbum.`);}
 }catch(e){toast(e.message);if(view==='album')loadPhotos();}});
document.addEventListener('input',event=>{if(event.target.id==='memory-search'){search=event.target.value;const caret=event.target.selectionStart;document.querySelector('#main').innerHTML=memories();const input=document.querySelector('#memory-search');input.focus();input.setSelectionRange(caret,caret);}});
modal.addEventListener('close',()=>{modal.querySelectorAll('iframe').forEach(f=>f.remove());});
window.addEventListener('hashchange',()=>{if(modal.open)close();view=location.hash.slice(1)||'inicio';filter='Todos';draw();window.scrollTo(0,0);});
async function boot(){try{await refresh();if(new URLSearchParams(location.search).has('auth')){toast('La conexión se canceló. Puedes intentarlo de nuevo en Ajustes.');history.replaceState(null,'',location.pathname);}}catch(e){app.innerHTML=`<section class="login"><img src="/icon.svg" width="64" height="64" alt=""><p class="eyebrow">UN ESPACIO PARA DOS</p><h1>El mundo es grande.<br><em>Lo nuestro es aquí.</em></h1><p>Fotos, canciones, planes y todos esos pequeños<br>momentos que hacen una vida juntos.</p><a href="/auth/google" class="btn primary">Entrar con Google ${icon('arrow')}</a><small>${icon('lock')} Solo las dos cuentas invitadas pueden entrar.</small><p class="fine-print">${esc(e.message)}</p></section>`;}}
// Refresca al regresar a la pestaña sin interrumpir una respuesta o un formulario abierto.
function safeToRefresh(){return !document.hidden&&state&&!modal.open&&!document.querySelector('form')&&!document.querySelector('input:focus')&&![...document.querySelectorAll('audio')].some(a=>!a.paused)&&view!=='album';}
async function sync(){
 if(document.hidden||!state||modal.open)return;
 if(view==='conectar'){
  const next=await api('/api/state');if(view!=='conectar'||modal.open)return;
  // Actualiza las respuestas de la pareja sin borrar el borrador que se está escribiendo.
  if(next.today!==state.today)return;
  state=next;const grid=document.querySelector('.answer-grid');
  if(grid)grid.innerHTML=state.settings.data.names.map((n,i)=>{const d=state.daily.find(d=>d.person===String(i));return `<article><span class="answer-avatar">${esc(n[0])}</span><b>${esc(n)}</b><p>${d?.answer?esc(d.answer):d?.answered?'Su respuesta está guardada. Se abrirá cuando ambos respondan.':'Todavía está pensando su respuesta.'}</p></article>`;}).join('');return;
 }
 if(!safeToRefresh())return;
 const currentView=view,next=await api('/api/state');if(view!==currentView||!safeToRefresh())return;
 if(JSON.stringify(next)!==JSON.stringify(state)){state=next;draw();}
}
document.addEventListener('visibilitychange',()=>{if(!document.hidden)sync().catch(()=>toast('No hay conexión. Tus cambios guardados siguen a salvo.'));});
setInterval(()=>sync().catch(()=>{}),30000);
setupPwa(html=>{app.innerHTML=html;}).then(async blocked=>{if(!blocked){await boot();tryMusic();}});
